<?php
require dirname(__DIR__) . '/includes/bootstrap.php';
require_admin();
$summary = db()->query("SELECT COUNT(*) AS order_count, COALESCE(SUM(total), 0) AS revenue, COALESCE(AVG(total), 0) AS average_order FROM orders WHERE status IN ('Shipped', 'Delivered')")->fetch();
$pending = db()->query("SELECT COUNT(*) FROM orders WHERE status = 'Pending'")->fetchColumn();
$topBooks = db()->query('SELECT oi.title_snapshot AS title, SUM(oi.quantity) AS units, SUM(oi.unit_price * oi.quantity) AS revenue FROM order_items oi JOIN orders o ON o.id = oi.order_id WHERE o.status IN (\'Shipped\', \'Delivered\') GROUP BY oi.title_snapshot ORDER BY units DESC, revenue DESC LIMIT 5')->fetchAll();
$recent = db()->query('SELECT id, full_name, total, status, created_at FROM orders ORDER BY created_at DESC LIMIT 8')->fetchAll();
render_header('Sales report');
?>
<section class="page-heading admin-heading"><div><div class="eyebrow"><span class="eyebrow-line"></span> PAPER & PINE ADMIN</div><h1>Sales report</h1><p>A snapshot of completed bookshop sales.</p></div><nav class="admin-nav"><a href="/LABSHEET%207/admin/index.php">Inventory</a><a href="/LABSHEET%207/admin/orders.php">Orders</a><a class="active" href="/LABSHEET%207/admin/reports.php">Sales report</a></nav></section>
<div class="report-stats"><article><span class="summary-eyebrow">COMPLETED REVENUE</span><strong><?= money($summary['revenue']) ?></strong><small>Shipped and delivered orders</small></article><article><span class="summary-eyebrow">COMPLETED ORDERS</span><strong><?= (int) $summary['order_count'] ?></strong><small>Average order <?= money($summary['average_order']) ?></small></article><article><span class="summary-eyebrow">AWAITING FULFILLMENT</span><strong><?= (int) $pending ?></strong><small>Pending customer orders</small></article></div>
<div class="report-columns"><section class="report-panel"><div class="section-heading"><div><div class="eyebrow"><span class="eyebrow-line"></span> READER FAVORITES</div><h2>Top-selling books</h2></div></div><?php if ($topBooks): ?><div class="top-books"><?php foreach ($topBooks as $index => $book): ?><div><span class="top-rank">0<?= $index + 1 ?></span><span><strong><?= e($book['title']) ?></strong><small><?= (int) $book['units'] ?> copies sold</small></span><b><?= money($book['revenue']) ?></b></div><?php endforeach; ?></div><?php else: ?><p class="muted-text">Completed sales will appear here.</p><?php endif; ?></section><section class="report-panel"><div class="section-heading"><div><div class="eyebrow"><span class="eyebrow-line"></span> RECENT ACTIVITY</div><h2>Latest orders</h2></div></div><?php if ($recent): ?><div class="recent-orders"><?php foreach ($recent as $order): ?><div><span><a href="/LABSHEET%207/invoice.php?id=<?= (int) $order['id'] ?>">#<?= (int) $order['id'] ?></a><small><?= e($order['full_name']) ?> · <?= e(date('M j', strtotime($order['created_at']))) ?></small></span><span><strong><?= money($order['total']) ?></strong><small class="status-pill status-<?= strtolower(e($order['status'])) ?>"><?= e($order['status']) ?></small></span></div><?php endforeach; ?></div><?php else: ?><p class="muted-text">No orders to show yet.</p><?php endif; ?></section></div>
<?php render_footer(); ?>
